// Mapea la respuesta del Agent (Message.Content) a campos utilizables.
let out = $json.output;
let parsed;
try {
  const raw = typeof out === 'string' ? (out.match(/\{[\s\S]*\}/)?.[0] ?? out) : out;
  parsed = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
} catch (e) {
  parsed = {};
}
// normaliza las claves a minuscula (tolera Sentimiento/sentimiento, Respuesta/respuesta, etc.)
const low = {};
for (const k in parsed) { low[k.toLowerCase()] = parsed[k]; }

const sentimiento = String(low.sentimiento || 'neutral').toLowerCase().trim();
const ruta = String(low.ruta || 'general').toLowerCase().trim();
const respuesta_ia = low.respuesta || low.respuesta_ia || low.mensaje || '';

return [{ json: { ...$json, sentimiento, ruta, respuesta_ia } }];
